"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[40643],{70426(e,a,o){o.r(a),o.d(a,{assets:()=>z,contentTitle:()=>c,default:()=>s,frontMatter:()=>t,metadata:()=>n,toc:()=>w});const n=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Wprowadzenie do kursu o praktycznych zastosowaniach oblicze\u0144 kwantowych.","source":"@site/i18n/pl/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Wprowadzenie do kursu o praktycznych zastosowaniach oblicze\u0144 kwantowych.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Overview","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Przegl\u0105d","permalink":"/learning/courses/quantum-business-foundations/"}}');var i=o(74848),r=o(28453);const t={description:"Wprowadzenie do kursu o praktycznych zastosowaniach oblicze\u0144 kwantowych.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},c="Wprowadzenie do praktycznych oblicze\u0144 kwantowych w najbli\u017cszej przysz\u0142o\u015bci {#introduction-to-practical-near-term-quantum-computing}",z={},w=[{value:"Do czego mog\u0105 si\u0119 przyda\u0107 komputery kwantowe",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Kwantowa u\u017cyteczno\u015b\u0107 i przewaga w najbli\u017cszej przysz\u0142o\u015bci",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Kr\xf3tkie podstawy teorii z\u0142o\u017cono\u015bci",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Od teorii z\u0142o\u017cono\u015bci do praktycznych dowod\xf3w",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Obszary zastosowa\u0144 i studia przypadku w kursie",id:"application-areas-and-course-case-studies",level:2},{value:"Symulacja hamiltonian\xf3w",id:"hamiltonian-simulation",level:3},{value:"Optymalizacja",id:"optimization",level:3},{value:"Kwantowe uczenie maszynowe",id:"quantum-machine-learning",level:3},{value:"R\xf3wnania r\xf3\u017cniczkowe cz\u0105stkowe",id:"partial-differential-equations",level:3},{value:"Podsumowanie",id:"conclusion",level:2}];function y(e){const a={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:["\n",(0,i.jsx)(a.header,{children:(0,i.jsx)(a.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Wprowadzenie do praktycznych oblicze\u0144 kwantowych w najbli\u017cszej przysz\u0142o\u015bci"})}),"\n",(0,i.jsx)(a.p,{children:"Od czasu, gdy ponad cztery dekady temu po raz pierwszy zaproponowano komputery kwantowe, pytanie brzmi: jak daleko to nowe podej\u015bcie mog\u0142oby przesun\u0105\u0107 granice oblicze\u0144? Teoretyczna informatyka da\u0142a nam kilka ekscytuj\u0105cych odpowiedzi. Komputery kwantowe mog\u0142yby rozk\u0142ada\u0107 du\u017ce liczby ca\u0142kowite na czynniki dramatycznie szybciej ni\u017c najlepsze znane metody klasyczne, przyspiesza\u0107 nieustrukturyzowane przeszukiwanie i w bardziej naturalny spos\xf3b symulowa\u0107 uk\u0142ady kwantowe. Jednak wiele z tych pomys\u0142\xf3w zak\u0142ada\u0142o przysz\u0142y, wielkoskalowy, odporny na b\u0142\u0119dy komputer kwantowy."}),"\n",(0,i.jsx)(a.p,{children:"Technologia nie osi\u0105gn\u0119\u0142a jeszcze wszystkich tych teoretycznych cel\xf3w, ale szybko si\u0119 rozwija. Badacze mog\u0105 ju\u017c u\u017cywa\u0107 procesor\xf3w kwantowych do badania rzeczywistych problem\xf3w naukowych i przemys\u0142owych. W tym kursie zdob\u0119dziemy praktyczne do\u015bwiadczenie z niekt\xf3rymi z najbardziej obiecuj\u0105cych zastosowa\u0144. Oszacujemy niskoenergetyczne w\u0142a\u015bciwo\u015bci z\u0142o\u017conego modelu molekularnego, zasymulujemy dynamik\u0119 sieciowej teorii cechowania i zbadamy, jak problem portfela finansowego mo\u017cna odwzorowa\u0107 na komputer kwantowy. Przyjrzymy si\u0119 te\u017c nowszym obszarom, w kt\xf3rych dopiero zaczynamy rozumie\u0107, co mog\u0105 zaoferowa\u0107 komputery kwantowe, w tym kwantowemu uczeniu maszynowemu (QML) i kwantowym podej\u015bciom do r\xf3wna\u0144 r\xf3\u017cniczkowych cz\u0105stkowych (PDE)."}),"\n",(0,i.jsx)(a.p,{children:"Wiele przyk\u0142ad\xf3w w tym kursie jest na tyle ma\u0142ych, \u017ce komputer klasyczny potrafi je rozwi\u0105za\u0107. To celowe. Celem jest zdobycie przez ciebie namacalnego do\u015bwiadczenia z ca\u0142ym procesem u\u017cywania komputera kwantowego do rozwi\u0105zania rzeczywistego problemu. Niekt\xf3re przyk\u0142ady reprezentuj\u0105 problemy, dla kt\xf3rych przewaga kwantowa mo\u017ce pojawi\u0107 si\u0119 w znacznie wi\u0119kszej skali. W innych przyk\u0142adach u\u017cywamy uproszczonej metody, aby szczeg\xf3\u0142y implementacji nie przes\u0142ania\u0142y g\u0142\xf3wnej idei kwantowej."}),"\n",(0,i.jsx)(a.p,{children:"Pod koniec kursu powiniene\u015b mie\u0107 og\xf3lny obraz g\u0142\xf3wnych zastosowa\u0144 kwantowych i intuicj\u0119, dlaczego komputery kwantowe mog\u0105 by\u0107 u\u017cyteczne w okre\u015blonych obszarach. Poznasz powszechne techniki reprezentowania problem\xf3w na komputerach kwantowych, dowiesz si\u0119, jak metody kwantowe i klasyczne wsp\xf3\u0142pracuj\u0105, i zaczniesz rozpoznawa\u0107, kt\xf3re narz\u0119dzia i kompromisy maj\u0105 znaczenie dla r\xf3\u017cnych rodzaj\xf3w problem\xf3w."}),"\n",(0,i.jsx)(a.p,{children:"W tej pierwszej lekcji om\xf3wimy podstawowe poj\u0119cia i terminologi\u0119, kt\xf3re pomagaj\u0105 zrozumie\u0107 zastosowania oblicze\u0144 kwantowych na wysokim poziomie, i przedstawimy przegl\u0105d g\u0142\xf3wnych obszar\xf3w zastosowa\u0144, kt\xf3rymi aktywnie zajmuje si\u0119 spo\u0142eczno\u015b\u0107 naukowa."}),"\n",(0,i.jsx)(a.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Do czego mog\u0105 si\u0119 przyda\u0107 komputery kwantowe"}),"\n",(0,i.jsx)(a.p,{children:"Komputery kwantowe s\u0105 cz\u0119sto przedstawiane jako konkurenci komputer\xf3w klasycznych, ale trafniej jest my\u015ble\u0107 o nich jako o wyspecjalizowanych zasobach w ramach wi\u0119kszych klasycznych przep\u0142yw\xf3w pracy. Wa\u017cne pytanie brzmi wi\u0119c: kt\xf3re cz\u0119\u015bci oblicze\u0144 s\u0105 szczeg\xf3lnie dobrze dopasowane do sprz\u0119tu kwantowego? Najbardziej intuicyjna odpowied\u017a dotyczy problem\xf3w, kt\xf3re ju\u017c s\u0105 kwantowe, takich jak zachowanie cz\u0105steczek, materia\u0142\xf3w i p\xf3l kwantowych. Procesor kwantowy mo\u017ce bezpo\u015brednio reprezentowa\u0107 i przetwarza\u0107 stany kwantowe, podczas gdy zasoby potrzebne do og\xf3lnego opisu klasycznego rosn\u0105 wyk\u0142adniczo wraz z rozmiarem uk\u0142adu."}),"\n",(0,i.jsx)(a.p,{children:"W przypadku problem\xf3w z klasycznymi danymi wej\u015bciowymi i wyj\u015bciowymi sytuacja jest bardziej subtelna, ale nadal s\u0105 dobre powody, by je bada\u0107. Problemy optymalizacyjne s\u0105 powszechne i ekonomicznie wa\u017cne, wi\u0119c nawet niewielka poprawa jako\u015bci rozwi\u0105zania lub czasu dzia\u0142ania mog\u0142aby by\u0107 cenna. Algorytmy kwantowe mog\u0105 te\u017c oferowa\u0107 nowe sposoby eksploracji skomplikowanych przestrzeni rozwi\u0105za\u0144 lub wykorzystania struktury w okre\u015blonych klasach problem\xf3w. Kwantowe uczenie maszynowe ma silne uzasadnienie teoretyczne dla pewnych problem\xf3w z klasycznymi danymi wej\u015bciowymi, w tym dla ustrukturyzowanej klasyfikacji i przetwarzania ogromnych zbior\xf3w danych. Pozostaje jednak otwartym pytaniem, czy te wyniki prze\u0142o\u017c\u0105 si\u0119 na praktyczn\u0105 przewag\u0119 na rzeczywistych danych klasycznych. R\xf3wnania r\xf3\u017cniczkowe cz\u0105stkowe opisuj\u0105 wiele wa\u017cnych uk\u0142ad\xf3w w nauce, in\u017cynierii i finansach, a algorytmy kwantowe mog\u0105 poprawi\u0107 skalowanie niekt\xf3rych wielowymiarowych symulacji i du\u017cych problem\xf3w algebry liniowej."}),"\n",(0,i.jsx)(a.p,{children:"We wszystkich trzech obszarach koszt przygotowania klasycznych danych wej\u015bciowych, uruchomienia oblicze\u0144 kwantowych i wydobycia u\u017cytecznej klasycznej odpowiedzi mo\u017ce jednak przewy\u017cszy\u0107 korzy\u015b\u0107 z kroku kwantowego. B\u0119dziemy pami\u0119ta\u0107 o tych praktycznych wyzwaniach, badaj\u0105c, jak metody kwantowe s\u0105 stosowane w ka\u017cdym z obszar\xf3w."}),"\n",(0,i.jsx)(a.h2,{id:"near-term-quantum-utility-and-advantage",children:"Kwantowa u\u017cyteczno\u015b\u0107 i przewaga w najbli\u017cszej przysz\u0142o\u015bci"}),"\n",(0,i.jsx)(a.p,{children:"Ten kurs nie dotyczy konkretnie przewagi kwantowej, ale rozmowa o niej jest nieunikniona. Podstawow\u0105 motywacj\u0105 zastosowa\u0144 kwantowych jest u\u017cycie zasob\xf3w kwantowych do poszerzenia tego, co komputery klasyczne potrafi\u0105 same: uzyskanie dok\u0142adniejszych wynik\xf3w, szybsze doj\u015bcie do rozwi\u0105za\u0144 lub rozwi\u0105zywanie problem\xf3w, kt\xf3re s\u0105 inaczej niedost\u0119pne. Poni\u017csze powi\u0105zane terminy pomagaj\u0105 nam jasno m\xf3wi\u0107 o post\u0119pach, kt\xf3re obserwujemy:"}),"\n",(0,i.jsxs)(a.ul,{children:["\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Przyspieszenie kwantowe:"})," Wraz ze wzrostem rozmiaru problemu czas potrzebny metodzie kwantowej ro\u015bnie korzystniej ni\u017c w przypadku najlepszej odpowiedniej metody klasycznej dla tego samego zadania."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Przewaga kwantowa:"})," Obliczenia z udzia\u0142em komputera kwantowego przewy\u017cszaj\u0105 najlepsze odpowiednie podej\u015bcia klasyczne w dobrze zdefiniowanym zadaniu i wed\u0142ug sensownej miary. Przewaga kwantowa nie jest pojedynczym, trwa\u0142ym kamieniem milowym, lecz ewoluuj\u0105c\u0105 granic\u0105, kt\xf3ra przesuwa si\u0119 wraz z popraw\u0105 metod kwantowych i klasycznych."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"U\u017cyteczno\u015b\u0107 kwantowa:"})," Obliczenia kwantowe wnosz\u0105 wk\u0142ad w u\u017cyteczny wynik naukowy lub techniczny. Dzia\u0142aj\u0105 w skali, g\u0142\u0119boko\u015bci i dok\u0142adno\u015bci wykraczaj\u0105cych poza praktyczn\u0105 klasyczn\u0105 symulacj\u0119 si\u0142ow\u0105, niekoniecznie przewy\u017cszaj\u0105c najlepsz\u0105 metod\u0119 klasyczn\u0105."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Algorytm bliskiej przysz\u0142o\u015bci:"})," Algorytm zaprojektowany dla obecnych procesor\xf3w kwantowych, wykorzystuj\u0105cy ograniczone g\u0142\u0119boko\u015bci obwod\xf3w i cz\u0119sto opieraj\u0105cy si\u0119 na klasycznym przetwarzaniu ko\u0144cowym i \u0142agodzeniu b\u0142\u0119d\xf3w zamiast pe\u0142nej kwantowej korekcji b\u0142\u0119d\xf3w."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Kwantowe obliczenia odporne na b\u0142\u0119dy:"})," W przysz\u0142o\u015bci obliczenia kwantowe b\u0119d\u0105 wykorzystywa\u0107 kwantow\u0105 korekcj\u0119 b\u0142\u0119d\xf3w do ochrony logicznych kubit\xf3w przez ca\u0142y czas oblicze\u0144. Gdy fizyczne poziomy b\u0142\u0119d\xf3w s\u0105 poni\u017cej progu odporno\u015bci na b\u0142\u0119dy, dodatkowe zasoby korekcji b\u0142\u0119d\xf3w mog\u0105 st\u0142umi\u0107 b\u0142\u0119dy logiczne do poziomu, jakiego wymagaj\u0105 d\u0142ugie, niezawodne obliczenia. Odporno\u015b\u0107 na b\u0142\u0119dy umo\u017cliwia znacznie g\u0142\u0119bsze algorytmy, w tym wielkoskalowe implementacje algorytmu Shora."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Wczesna odporno\u015b\u0107 na b\u0142\u0119dy:"})," Odporno\u015b\u0107 na b\u0142\u0119dy oznacza, \u017ce b\u0142\u0119dy s\u0105 t\u0142umione, a nie ca\u0142kowicie eliminowane. We wczesnych uk\u0142adach odpornych na b\u0142\u0119dy nadal trzeba uwzgl\u0119dnia\u0107 pozosta\u0142e b\u0142\u0119dy logiczne, a g\u0142\u0119boko\u015b\u0107 niezawodnych obwod\xf3w pozostaje ograniczona."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Algorytm heurystyczny:"})," Metoda zaprojektowana tak, aby w praktyce znajdowa\u0107 dobre rozwi\u0105zanie bez gwarancji optymalnej odpowiedzi ani okre\u015blonego czasu dzia\u0142ania."]}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(a.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Kr\xf3tkie podstawy teorii z\u0142o\u017cono\u015bci"}),"\n",(0,i.jsx)(a.p,{children:"W niekt\xf3rych obszarach zastosowa\u0144 mamy silne teoretyczne powody, by oczekiwa\u0107, \u017ce komputer kwantowy mo\u017ce mie\u0107 przewag\u0119. Aby zrozumie\u0107, sk\u0105d bierze si\u0119 ta pewno\u015b\u0107, potrzebujemy odrobiny s\u0142ownictwa z teorii z\u0142o\u017cono\u015bci."}),"\n",(0,i.jsx)(a.p,{children:"Teoria z\u0142o\u017cono\u015bci bada, jak zasoby potrzebne do rozwi\u0105zania problemu rosn\u0105 wraz ze wzrostem problemu. Daje nam u\u017cyteczn\u0105 map\u0119 tego, gdzie przyspieszenie kwantowe mo\u017ce by\u0107 mo\u017cliwe. Kilka termin\xf3w jest szczeg\xf3lnie wa\u017cnych w tym kursie:"}),"\n",(0,i.jsxs)(a.ul,{children:["\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"P:"})," Problemy, kt\xf3re komputer klasyczny potrafi rozwi\u0105za\u0107 efektywnie, co oznacza, \u017ce wymagane zasoby rosn\u0105 wielomianowo wraz z rozmiarem problemu."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"NP:"})," Problemy, dla kt\xf3rych mo\u017cna efektywnie sprawdzi\u0107 proponowane rozwi\u0105zanie, nawet je\u015bli jego znalezienie mo\u017ce by\u0107 bardzo trudne."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"NP-trudne:"})," Problemy, kt\xf3re s\u0105 co najmniej tak trudne jak ka\u017cdy problem w NP. Problem NP-trudny niekoniecznie nale\u017cy do NP. Wiele problem\xf3w optymalizacyjnych jest NP-trudnych."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"NP-zupe\u0142ne:"})," Problemy, kt\xf3re s\u0105 zar\xf3wno NP-trudne, jak i nale\u017c\u0105 do NP. S\u0105 to najtrudniejsze problemy decyzyjne w NP."]}),"\n"]}),"\n",(0,i.jsxs)(a.li,{children:["\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"BQP:"})," Problemy, kt\xf3re komputer kwantowy potrafi rozwi\u0105za\u0107 efektywnie z ograniczonym prawdopodobie\u0144stwem b\u0142\u0119du."]}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(a.p,{children:"Niekt\xf3re zale\u017cno\u015bci mi\u0119dzy tymi kategoriami s\u0105 znane. P zawiera si\u0119 zar\xf3wno w NP, jak i w BQP, poniewa\u017c problem, kt\xf3ry mo\u017cna efektywnie rozwi\u0105za\u0107 na komputerze klasycznym, mo\u017cna te\u017c sprawdzi\u0107 klasycznie i rozwi\u0105za\u0107 na komputerze kwantowym. Inne zale\u017cno\u015bci pozostaj\u0105 otwarte. Nie wiemy, czy P r\xf3wna si\u0119 NP ani czy NP zawiera si\u0119 w BQP. Badacze zazwyczaj uwa\u017caj\u0105 jednak, \u017ce P jest mniejsze zar\xf3wno od NP, jak i od BQP oraz \u017ce komputery kwantowe nie potrafi\u0105 efektywnie rozwi\u0105za\u0107 ka\u017cdego problemu NP-zupe\u0142nego. M\xf3wi\u0105c prosto, komputer kwantowy nie jest magicznym pude\u0142kiem, kt\xf3re natychmiast rozwi\u0105zuje ka\u017cdy trudny problem."}),"\n",(0,i.jsx)(a.p,{children:"Najsilniejsze argumenty oparte na z\u0142o\u017cono\u015bci na rzecz oblicze\u0144 kwantowych dotycz\u0105 okre\u015blonych rodzaj\xf3w problem\xf3w. Algorytm Shora skaluje si\u0119 dramatycznie lepiej ni\u017c najlepsze znane algorytmy klasyczne dla rozk\u0142adu na czynniki i logarytm\xf3w dyskretnych, cho\u0107 nie udowodniono, \u017ce rozk\u0142ad na czynniki le\u017cy poza P. Og\xf3lna symulacja kwantowa ma r\xf3wnie\u017c silne podstawy teoretyczne. Niekt\xf3re problemy symulacji kwantowej s\u0105 BQP-zupe\u0142ne, co oznacza, \u017ce efektywne rozwi\u0105zanie ich klasycznie r\xf3wna\u0142oby si\u0119 efektywnej symulacji dowolnych oblicze\u0144 kwantowych. Taka efektywna symulacja klasyczna jest wysoce nieprawdopodobna, co jest jednym z powod\xf3w, dla kt\xf3rych kwantowa symulacja hamiltonian\xf3w uchodzi za tak obiecuj\u0105cy obszar zastosowa\u0144."}),"\n",(0,i.jsx)(a.p,{children:"Niekt\xf3re wielowymiarowe PDE mo\u017cna sprowadzi\u0107 do BQP-zupe\u0142nych problem\xf3w uk\u0142ad\xf3w liniowych, co daje nam silny pow\xf3d, by oczekiwa\u0107 przyspieszenia kwantowego, gdy dane wej\u015bciowe i wyj\u015bciowe mo\u017cna obs\u0142u\u017cy\u0107 efektywnie. QML ma podobne przyk\u0142ady: niekt\xf3re zadania z danymi kwantowymi s\u0105 BQP-zupe\u0142ne, a niekt\xf3re modele kwantowe potrafi\u0105 generowa\u0107 pr\xf3bki, kt\xf3re trudno odtworzy\u0107 klasycznie."}),"\n",(0,i.jsx)(a.p,{children:"W przypadku optymalizacji sytuacja jest mniej oczywista. Nie oczekuje si\u0119, \u017ce komputery kwantowe efektywnie rozwi\u0105\u017c\u0105 dowolne problemy NP-trudne, ale mog\u0105 nadal pomaga\u0107 w problemach ustrukturyzowanych, w poszczeg\xf3lnych instancjach lub w konkretnych krokach przep\u0142ywu pracy optymalizacji. Algorytm Grovera, na przyk\u0142ad, daje kwadratowe przyspieszenie dla nieustrukturyzowanego przeszukiwania. To znacz\u0105ca poprawa, nawet je\u015bli pierwiastek kwadratowy z astronomicznie du\u017cej przestrzeni poszukiwa\u0144 nadal mo\u017ce by\u0107 astronomiczny."}),"\n",(0,i.jsx)(a.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Od teorii z\u0142o\u017cono\u015bci do praktycznych dowod\xf3w"}),"\n",(0,i.jsx)(a.p,{children:"Teoria z\u0142o\u017cono\u015bci mo\u017ce nam powiedzie\u0107, gdzie przyspieszenie kwantowe mo\u017ce by\u0107 mo\u017cliwe, ale zwykle nie powie, jak metoda sprawdzi si\u0119 w konkretnym problemie lub na konkretnym komputerze kwantowym. Wiele metod stosowanych na obecnym sprz\u0119cie jest heurystycznych. S\u0105 zaprojektowane, by w praktyce znajdowa\u0107 dobre odpowiedzi, ale nie gwarantuj\u0105 najlepszej mo\u017cliwej odpowiedzi ani okre\u015blonego czasu dzia\u0142ania."}),"\n",(0,i.jsx)(a.p,{children:"Heurystyki nie s\u0105 wyj\u0105tkowe dla oblicze\u0144 kwantowych, a nazwanie metody heurystyczn\u0105 nie oznacza, \u017ce jest zawodna lub nienaukowa. Klasyczna optymalizacja, uczenie maszynowe i chemia obliczeniowa w du\u017cym stopniu opieraj\u0105 si\u0119 na heurystykach, gdy dok\u0142adne rozwi\u0105zanie by\u0142oby zbyt kosztowne. Kwantowa heurystyka mo\u017ce oferowa\u0107 nowy spos\xf3b eksploracji przestrzeni rozwi\u0105za\u0144, przygotowywania u\u017cytecznych stan\xf3w lub wskazywania obiecuj\u0105cych kandydat\xf3w. To, czy dzia\u0142a dobrze, jest pytaniem empirycznym: musimy j\u0105 uruchomi\u0107 i zmierzy\u0107 wynik."}),"\n",(0,i.jsx)(a.p,{children:"Poniewa\u017c heurystyki nie maj\u0105 gwarancji wydajno\u015bci, oceniamy je za pomoc\u0105 jasnej miary sukcesu, silnych klasycznych punkt\xf3w odniesienia i test\xf3w dla r\xf3\u017cnych rozmiar\xf3w problemu. Pomaga to zobaczy\u0107, gdzie metoda dzia\u0142a dobrze i jak jej wydajno\u015b\u0107 zmienia si\u0119 wraz ze skal\u0105 problemu."}),"\n",(0,i.jsx)(a.h2,{id:"application-areas-and-course-case-studies",children:"Obszary zastosowa\u0144 i studia przypadku w kursie"}),"\n",(0,i.jsx)(a.p,{children:"Kurs organizujemy wok\xf3\u0142 czterech szerokich obszar\xf3w zastosowa\u0144. Nie obejmuj\u0105 one ka\u017cdego mo\u017cliwego u\u017cycia komputera kwantowego, ale daj\u0105 nam u\u017cyteczny spos\xf3b por\xf3wnania, gdzie le\u017c\u0105 najsilniejsze argumenty i gdzie s\u0105 otwarte pytania."}),"\n",(0,i.jsx)(a.h3,{id:"hamiltonian-simulation",children:"Symulacja hamiltonian\xf3w"}),"\n",(0,i.jsx)(a.p,{children:"Symulacja hamiltonian\xf3w obejmuje szacowanie energii, badanie w\u0142a\u015bciwo\u015bci chemicznych i materia\u0142owych oraz modelowanie zmian uk\u0142ad\xf3w kwantowych w czasie. Si\u0119ga chemii, nauki o materia\u0142ach, fizyki materii skondensowanej oraz fizyki wysokich energii i j\u0105drowej. Nasze studia przypadku badaj\u0105 silnie skorelowany model \u017celazo-siarka przy u\u017cyciu kwantowej diagonalizacji opartej na pr\xf3bkowaniu i symuluj\u0105 dynamik\u0119 hadron\xf3w za pomoc\u0105 reprezentacji sieciowej uwzgl\u0119dniaj\u0105cej symetrie. To dwa przyk\u0142ady ze znacznie wi\u0119kszej dziedziny, kt\xf3ra obejmuje te\u017c mechanizmy reakcji, materia\u0142y magnetyczne i inn\u0105 dynamik\u0119 wielu cia\u0142."}),"\n",(0,i.jsx)(a.h3,{id:"optimization",children:"Optymalizacja"}),"\n",(0,i.jsx)(a.p,{children:"Optymalizacja pojawia si\u0119 wsz\u0119dzie, od finans\xf3w i logistyki po planowanie i systemy energetyczne. Jest to te\u017c obszar, w kt\xf3rym trudno wykaza\u0107 przewag\u0119, poniewa\u017c klasyczne solwery s\u0105 niezwykle wydajne, a odwzorowania kwantowe mog\u0105 dodawa\u0107 kosztowny narzut. Nasze studium przypadku wykorzystuje wyb\xf3r portfela, aby zbada\u0107, jak problem optymalizacyjny jest reprezentowany, uruchamiany i testowany, bez zak\u0142adania, \u017ce komputer kwantowy automatycznie znajdzie dok\u0142adne optimum."}),"\n",(0,i.jsx)(a.h3,{id:"quantum-machine-learning",children:"Kwantowe uczenie maszynowe"}),"\n",(0,i.jsx)(a.p,{children:"Kwantowe uczenie maszynowe pyta, czy obwody kwantowe lub dane kwantowe mog\u0105 poprawi\u0107 zadanie uczenia. Wa\u017cne pytania dotycz\u0105 kodowania danych, kosztu trenowania, uog\xf3lniania i por\xf3wnania z silnymi modelami klasycznymi."}),"\n",(0,i.jsx)(a.h3,{id:"partial-differential-equations",children:"R\xf3wnania r\xf3\u017cniczkowe cz\u0105stkowe"}),"\n",(0,i.jsx)(a.p,{children:"R\xf3wnania r\xf3\u017cniczkowe cz\u0105stkowe opisuj\u0105 uk\u0142ady takie jak p\u0142yny, ciep\u0142o i fale. Algorytmy kwantowe mog\u0105 przyspiesza\u0107 cz\u0119\u015bci niekt\xf3rych przep\u0142yw\xf3w pracy PDE, ale przygotowanie danych i wydobycie u\u017cytecznej klasycznej odpowiedzi mog\u0105 by\u0107 g\u0142\xf3wnymi kosztami. Konkretne studium przypadku jest wci\u0105\u017c opracowywane."}),"\n",(0,i.jsx)(a.p,{children:"W kolejnych lekcjach w ka\u017cdym obszarze zadamy te same podstawowe pytania: jaki jest problem, dlaczego obliczenia kwantowe mog\u0142yby pom\xf3c, jakie s\u0105 ograniczenia i co faktycznie pokazuj\u0105 dowody? Zaczniemy od symulacji hamiltonian\xf3w, gdzie sam problem jest kwantowy."}),"\n",(0,i.jsx)(a.h2,{id:"conclusion",children:"Podsumowanie"}),"\n",(0,i.jsx)(a.p,{children:"Om\xf3wili\u015bmy sporo materia\u0142u, ale g\u0142\xf3wna idea jest prosta: komputery kwantowe to wyspecjalizowane narz\u0119dzia, a ich warto\u015b\u0107 zale\u017cy od u\u017cycia w\u0142a\u015bciwej metody kwantowej do w\u0142a\u015bciwego problemu lub fragmentu wi\u0119kszego problemu. Symulacja hamiltonian\xf3w ma najja\u015bniejsze podstawy teoretyczne, optymalizacja ma dojrza\u0142y zestaw metod heurystycznych i test\xf3w por\xf3wnawczych, a QML i PDE oferuj\u0105 obiecuj\u0105ce kierunki, kt\xf3re wci\u0105\u017c si\u0119 rozwijaj\u0105."}),"\n",(0,i.jsx)(a.p,{children:"W kolejnych lekcjach przejdziemy od tego szerokiego przegl\u0105du do praktycznych przyk\u0142ad\xf3w. Dla ka\u017cdego zastosowania zapytamy, jaki problem pr\xf3bujemy rozwi\u0105za\u0107, jak\u0105 rol\u0119 odgrywa komputer kwantowy, jak interpretowany jest wynik i czego mo\u017cemy si\u0119 z niego nauczy\u0107. Celem jest rozwini\u0119cie twojej intuicji, gdzie obliczenia kwantowe mog\u0105 pom\xf3c i co jest potrzebne, by zamieni\u0107 obiecuj\u0105cy pomys\u0142 w rzeczywiste obliczenia."}),"\n"]})}function s(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(y,{...e})}):y(e)}},28453(e,a,o){o.d(a,{R:()=>t,x:()=>c});var n=o(96540);const i={},r=n.createContext(i);function t(e){const a=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:t(e.components),n.createElement(r.Provider,{value:a},e.children)}}}]);